# -*- coding: utf-8 -*-
S = "поиск по классам дефектов: ссылки на «предыдущее задание» (26–29.09)"
P = {}
FUN = (r"Даны функции: а) $y=\sqrt{1-x^{2}}$; б) $y=\sqrt{1-x^{2}}$, $X=\left[0; \dfrac{\sqrt{3}}{2}\right]$; в) $y=\sqrt{1-x^{2}}$, $X=\left[-\dfrac{\sqrt{3}}{2}; 1\right]$; "
       r"г) $y=\dfrac{30}{\sqrt{100-x^{2}}}$, $X=[-8; 1]$; д) $y=\dfrac{1}{\sqrt{1-x^{2}}}$, $X=\left(-\dfrac{\sqrt{2}}{2}; 0\right)$; е) $y=\log_{2}\sqrt{x^{2}-1}$; "
       r"ж) $y=\dfrac{1}{\sqrt{1-x^{2}}}$, $X=\left[-\dfrac{\sqrt{3}}{2}; \dfrac{\sqrt{3}}{2}\right]$; з) $y=\log_{2}\sqrt{1-x^{2}}$ (если множество $X$ не указано, берётся естественная область определения). ")
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
WHY = "условие ссылалось на «предыдущее задание» и не решалось само по себе; условие восстановлено по упр. 10 того же параграфа (тот же пункт в банке), ключ пересчитан: "
E("G11_TB_1_3_1_11_1", WHY + "снизу ограничены а, б, в, г, д, ж (значения ≥ 0, ≥ 1/2, ≥ 0, ≥ 3, > 1, ≥ 1); е и з (логарифм) — нет, при аргументе корня → 0⁺ значение → −∞; прежний ключ включал з ошибочно",
  q=FUN + "Какие из этих функций ограничены снизу на своей области определения?", k="а, б, в, г, д, ж",
  dnew={0: ("а, б, в, г, д, е, ж, з", "Ученик счёл ограниченными снизу все функции, но у $y=\\log_{2}\\sqrt{x^{2}-1}$ и $y=\\log_{2}\\sqrt{1-x^{2}}$ при приближении подкоренного выражения к нулю значение уходит в $-\\infty$."),
        1: ("а, б, в, г, д, ж, з", "Ученик верно отметил а–д и ж, но добавил з: $y=\\log_{2}\\sqrt{1-x^{2}}\\le 0$ ограничена сверху нулём, а снизу не ограничена ($y\\to-\\infty$ при $x\\to\\pm1$)."),
        2: ("а, б, в, г, д", "Ученик пропустил ж: на $\\left[-\\frac{\\sqrt{3}}{2}; \\frac{\\sqrt{3}}{2}\\right]$ функция $y=\\frac{1}{\\sqrt{1-x^{2}}}$ принимает значения из $[1; 2]$, то есть ограничена снизу единицей.")})
E("G11_TB_1_3_1_11_2", WHY + "сверху ограничены а, б, в, г, д, ж, з (≤ 1, ≤ 1, ≤ 1, ≤ 5, < √2, ≤ 2, ≤ 0); е — нет (при |x| → ∞ значение → +∞); прежний ключ верный, но с латинской «a» и без условия",
  q=FUN + "Какие из этих функций ограничены сверху на своей области определения?", k="а, б, в, г, д, ж, з",
  dnew={0: ("а, б, в, г, д, е, ж, з", "Ученик включил е: $y=\\log_{2}\\sqrt{x^{2}-1}$ при $x\\to\\pm\\infty$ растёт неограниченно, сверху не ограничена."),
        1: ("а, б, в, г, д, ж", "Ученик забыл з: $y=\\log_{2}\\sqrt{1-x^{2}}\\le\\log_{2}1=0$, то есть функция ограничена сверху нулём."),
        2: ("а, б, в, г, ж, з", "Ученик не включил д, решив, что открытый промежуток $\\left(-\\frac{\\sqrt{2}}{2}; 0\\right)$ мешает ограниченности; но на нём $1<y<\\sqrt{2}$, функция ограничена сверху.")})
E("G11_TB_1_3_1_11_3", WHY + "ограничены (и снизу, и сверху) а, б, в, г, д, ж; е и з не ограничены снизу; прежний ключ включал з ошибочно, а один из прежних неверных вариантов («а, б, в, г, д, ж») был верным ответом",
  q=FUN + "Какие из этих функций ограничены на своей области определения?", k="а, б, в, г, д, ж",
  dnew={0: ("а, б, в, г, д, ж, з", "Ученик включил з, проверив только ограниченность сверху ($y\\le 0$); снизу $y=\\log_{2}\\sqrt{1-x^{2}}$ уходит в $-\\infty$, поэтому не ограничена."),
        1: ("а, б, в, г, д, е, ж, з", "Ученик счёл ограниченными обе логарифмические функции; но и е, и з неограничены снизу ($\\log_{2}$ от числа, стремящегося к нулю, уходит в $-\\infty$), а е ещё и сверху."),
        2: ("а, б, в, г, ж", "Ученик не включил д, но на $\\left(-\\frac{\\sqrt{2}}{2}; 0\\right)$ значения лежат в $(1; \\sqrt{2})$, то есть $1<y<\\sqrt{2}$ — функция ограничена.")})
for _t in ("G5_TB_31_552", "G5_TB_31_555"):
    E(_t, "лишняя ссылка на «предыдущую практическую работу» не нужна: сумма углов треугольника 180°, третий угол вычисляется по двум данным; ключ проверен (180 − a − b)",
      qrep=("Исходя из результата предыдущей практической работы. ", ""))
